def classification(cid):
 if cid=='python.console_input_output':
  prompt='Read each supplied implementation for the same input Ada. Decide whether it requests a name, stores only the entered text in label, and displays Hello Ada with one space and a final newline.'
  items=[('label = input("Name: ")\nprint("Hello", label)','meets','input returns entered text without the prompt or trailing newline; print supplies the required space and newline.'),('label = input("Name: ")\nprint("Hello", label, sep="")','violates','An empty sep removes the space between Hello and Ada.'),('label = input("Name: ")\nprint("Hello", label, end="")','violates','An empty end removes the required final newline.')]
 elif cid=='python.running_scripts':
  prompt='Read each recorded pair of script runs. The supplied executable is selected_python and the saved file is report.py. Decide whether the record meets the criterion: explicit executable plus script path, Ready on standard output in both runs, and separately requested process statuses changing from 0 to 2.'
  items=[('Command for both saved versions: selected_python report.py\nVersion A: import sys; print("Ready"); sys.exit(0)\nRecorded stdout: Ready\\n ; process status: 0\nVersion B: import sys; print("Ready"); sys.exit(2)\nRecorded stdout: Ready\\n ; process status: 2','meets','The explicit executable receives the script path; printed output stays the same while requested statuses change.'),('Command: selected_python\nSaved report.py contains print("Ready")\nRecord claims that this command executed report.py.','violates','No script path was passed to the selected executable, so this does not demonstrate invocation of the saved script.'),('Command for both versions: selected_python report.py\nVersion A: import sys; print("Ready"); sys.exit(0)\nVersion B: import sys; print("Ready"); sys.exit(2)\nRecord labels Ready as the process status and 0/2 as standard output.','violates','The record swaps printed standard output with the separate requested process statuses.')]
 else:
  prompt='Read each fresh interactive-session record and decide whether it correctly enters commands without prompt characters, uses the retained quantity binding, and distinguishes displayed output from input. The assignment is quantity = 3 and the expression is quantity * (4 + 1).'
  ns={};exec('quantity = 3',ns);output=eval('quantity * (4 + 1)',ns)
  items=[(f'Typed command: quantity = 3\nDisplayed result of assignment: none\nTyped command: quantity * (4 + 1)\nDisplayed result: {output}\nExplanation: the expression uses quantity retained as 3.','meets','The assignment retains its binding; the later expression uses it and displays a result.'),('Typed command: >>> quantity = 3\nExplanation: prompt markers must be included in typed commands.','violates','Prompt markers are not part of the command and must not be copied.'),(f'Typed command: quantity = 3\nTyped command: quantity * (4 + 1)\nDisplayed result: {output}\nExplanation: the unprompted result line is another command to type.','violates','An unprompted tutorial result is output, not another command.')]
 return {'prompt':prompt,'buckets':[{'bucket_id':'meets','label':'Meets the criterion'},{'bucket_id':'violates','label':'Violates the criterion'}],'items':[{'item_id':f'i{i+1}','text':v[0]} for i,v in enumerate(items)]},{'assignments':{f'i{i+1}':v[1] for i,v in enumerate(items)},'item_feedback':{f'i{i+1}':{'message':v[2]} for i,v in enumerate(items)}}

